<?php
require_once __DIR__.'/includes/functions.php';require_role(['admin']);$pageTitle='Manage members';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($id===current_user()['id'])$error='You cannot deactivate your own account.';elseif($action==='toggle'){$s=db()->prepare("UPDATE users SET status=IF(status='active','inactive','active') WHERE id=? AND role IN ('student','librarian')");$s->execute([$id]);flash('success','Member status updated.');redirect('/members.php');}}
$users=db()->query("SELECT u.id,u.name,u.email,u.role,u.status,u.student_no,u.created_at,(SELECT COUNT(*) FROM issues i WHERE i.user_id=u.id AND i.status='issued') AS active_loans FROM users u WHERE u.role IN ('student','librarian') ORDER BY u.created_at DESC")->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="mb-4"><p class="text-primary small text-uppercase fw-bold mb-1">Administration</p><h1 class="page-title mb-1">Members & librarians</h1><p class="muted mb-0">Review accounts and control access.</p></div><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><div class="d-flex justify-content-end mb-3"><input class="form-control" style="max-width:280px" placeholder="Search members..." data-search-target="#membersRows"></div><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Student ID</th><th>Active loans</th><th>Status</th><th>Action</th></tr></thead><tbody id="membersRows"><?php foreach($users as $u): ?><tr data-searchable><td><strong><?=e($u['name'])?></strong></td><td><?=e($u['email'])?></td><td><?=e(ucfirst($u['role']))?></td><td><?=e($u['student_no']??'—')?></td><td><?=(int)$u['active_loans']?></td><td><span class="badge-soft <?=$u['status']==='active'?'badge-available':'badge-unavailable'?>"><?=e(ucfirst($u['status']))?></span></td><td><form method="post" onsubmit="return confirm('Change this member account status?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$u['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-sm btn-outline-primary" type="submit"><?=$u['status']==='active'?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php require __DIR__.'/includes/footer.php'; ?>
